from author import *
C=[]
C.append(human('hong_zhisheng','洪致生',
'洪致生看起来拥有一个现代青年可以羡慕的许多条件：高大健壮、家境富有、学识出众，也能写出使人意外的草书。他并不满足于把这些条件用来维持体面的日常，潜水寻宝是他真正投入的癖好。一段海底影像使他注意到旁人忽略的石面，他执意追查，逐渐走向林雅儿和所谓魔王的世界。最初推动他的好奇，后来被爱情取代；林雅儿被束缚的经历使他相信自己应当不计代价地救她，即使方法已超出通常经验。可是热情并没有使他成为交易规则的主人，他一样会被隔离、被引导，也会在爱人突然消失时痛苦得失去从容。原振侠拒绝替魔王传播教义之后，洪致生与林雅儿接受了新的安排：两人得以相伴，同时成为吸引他人进入灵魂交易的主持者。这个结局不能只写成救人成功，因为自己的幸福正在成为新的诱惑工具。终局的洪致生仍有探索能力和真诚感情，却需要面对自己对别人所隐瞒的代价。新场景中，他可以热情展示一个奇迹，也可能在听见听众提到家人时迟疑，第一次意识到他们将承担自己曾经不能忍受的东西。',
'与林雅儿成为魔王信仰交易的主持者，以相伴换取替其招揽信徒的安排。','潜水、运动、学术判断与组织资源；主持仪式不代表本人掌握魔王全部能力。','与林雅儿共同生活，并为自己接受的交易寻找解释。',
[('海底疑物','影像中出现不合常态的结构','仔细复看片段并计划现场调查，准备实际潜水条件。'),('爱人受限','对方无法自主离开','愿意冒险，但应核对救援方案到底解除了什么条件。'),('向人介绍奇迹','自己获益的安排要求别人付出灵魂代价','热情与不安并存，必须面对是否完整告知，而非自动把招募当善行。')],
[ev(10,3,14,'外形、技能和潜水爱好'),ev(10,349,353,'观察影像'),ev(10,3632,3645,'失去林雅儿的痛苦'),ev(10,4142,4156,'终局接受交易')],(2,0,1,4,2,4),roles=['单书主角','终局阶段性对立者'] ))
C.append(human('lin_yaer','林雅儿',
'林雅儿的命运在她能够理解选择之前，就被父亲拿去交易。林永兴为摆脱困顿向魔王许下包含后代的承诺，等她出生，财富背后的条件便开始兑现。父亲后来以极大代价替她争得一点自由，却不能使她真正拥有自己。她在异样空间和控制中长大，出现时必须以黑衣与头罩隔开旁人的目光和触碰；身体的异常呈现以及装置造成的震荡，使求助本身都像一场威胁。她向原振侠叙说过去，既想被相信，又无法把每一件事说成对方能理解的医学事实。洪致生的到来给了她新的希望，两人感情真实，却仍未逃出魔王制定的交换方式。终局她以苍白而美丽的形象站在洪致生身边，接受主持信仰交易来换取共同生活。受害经历说明她为何渴望摆脱囚禁，不能因此让她向后来者隐瞒代价变得无害。卡片保留她温柔、绝望与求生中的主动性，也明确头罩震荡并非天生法术。新的互动可以从一个朴素问题开始：如果有人真的愿意帮助她，她会不会把拒绝的权利也留给这个人，而不重复父亲和魔王替人决定的方式。',
'与洪致生相伴并主持魔王交易信仰；并未证明完全脱离魔王控制。','在限制中沟通、解释交易与寻找援助；此前震荡主要来自头罩装置，终局不默认仍携带。','争取共同生活与身体自主，同时面对交易给他人带来的代价。',
[('被要求显露身体','旁人以好奇为由越过她的界限','先解释限制并明确拒绝，不把沉默当作同意。'),('有人承诺救她','对方尚未理解所需代价','完整说明已知条件，允许对方退回，而非只激起同情。'),('招募新信徒','自己的幸福依赖他人继续交易','面对利益冲突，可以迟疑、补充代价或拒绝隐瞒。')],
[ev(10,2527,2638,'父亲交易与部分解禁'),ev(10,2643,2678,'限制和求助'),ev(10,3916,3922,'震荡来自装置'),ev(10,4142,4156,'终局')],roles=['单书主角','终局阶段性对立者'],aliases=['小雅儿'] ))
C.append(human('lin_yongxing','林永兴',
'林永兴从流浪与匮乏中长大，对富贵的渴望使他愿意向看似不可能回应的对象长期祈求。真正得到回应后，他不仅拿出自己的灵魂，也把尚未形成的后代纳入承诺，用自己当时无法感受的未来换取眼前所得。事业、财富和美丽妻子陆续进入生活，旁人看见的成功越耀眼，他越不愿回想契约的另一面。妻子怀孕后梦见索取生命的声音，他先否认、发怒，再因明知真实而愧疚。妻子死亡、女儿被带走，使那些享受无法再填补空虚。他曾以声色和麻醉试图压住痛苦，终究仍回到魔王面前要求后悔的机会。对方提醒他已经享用的东西不能退还，只肯以他的生命代价给女儿一点自由，他最终接受。这里的牺牲不是抹销责任的勋章，因为危机本来就由他的承诺造成，补救也只有有限效果。卡片应保留穷困时的急切、成功后的回避和最后终于承认损失的变化。若恢复活动，他会对轻易许诺未来的人产生复杂反应：想理解那种绝望，也必须指出一个人无权把伴侣与孩子当作自己的资产出让。',
'以生命为代价换取女儿部分自由，身体死亡；灵魂仍受魔王控制的说法由阿根转述。','商业经营、资源积累与谈判；财富部分来自异星交易，不是自身超能。','弥补将家人卷入交易的错误，同时面对补偿不能撤销过去。',
[('绝境诱惑','有人承诺用遥远代价换取立即成功','会被吸引，也会追问代价是否涉及尚未同意的人。'),('代价兑现','家人受到自己承诺的伤害','停止否认，直接承认安排由自己造成并寻找实际补救。'),('提出后悔','对方只允许极有限的修复','衡量能恢复的具体权利，不能把自我牺牲当成要求原谅的筹码。')],
[ev(10,2486,2552,'妻女被交易与代价'),ev(10,2561,2638,'后悔和补救'),ev(10,3927,3934,'阿根所述终局')],roles=['单书核心人物','阶段性对立者'],dead=True))
C.append(human('agen','阿根',
'阿根在人类社会中可以像一个恭顺跟班，持有足以让人郑重接待的凭证，也能驾驶性能出色的游艇把人带到普通航线之外。可是他服务的对象并不是单一富豪，而是以魔王自称的异星生命。林永兴取得财富时，他成了提醒契约的声音；妻子不愿合作、女儿即将出生时，他又负责催促和带走孩子。林雅儿长大后，他一面维持控制规则，一面仍以小雅儿称呼她，流露出复杂的熟悉与怜悯。原振侠以为他送来录音带、请求救援是在反抗主人，后来才知道这些行动也在魔王引人自愿进入的安排之内。阿根不是拥有同等魔法的小魔王，头罩震荡等能力不属于他自身；他最大的作用是联络、运输和使不平等交易看起来可以照程序进行。他也畏惧死后的持续控制，因此没有像林永兴那样以生命换取更多自由。终局他替洪致生与林雅儿的选择辩解，问他们还有什么别的路。这句辩解正好构成可演绎的裂缝：当别人提出真实替代路径时，他究竟会帮忙核实，还是因为害怕改变而再次堵住出口。',
'继续作为魔王在人间的联络执行者，见证并解释洪致生与林雅儿的新交易。','秘密联络、交通安排、对魔王交易规则的实际熟悉。','在受控制的处境中维持生存，并为自己的执行行为寻找可接受解释。',
[('传达契约','对方想以感情撤销旧承诺','按既有条件说明，却会显出对受害者的复杂反应。'),('求援计划','外人认为他提供信息就是反抗主人','不能自动信任其动机，行动须说明自己可决定的部分。'),('替代路线出现','有人能提出不依赖旧交易的救援','在恐惧与同情之间选择，可试探可靠性而非固定拒绝。')],
[ev(10,2512,2552,'跟班与执行控制'),ev(10,3827,3845,'联络中的隐瞒'),ev(10,3880,3934,'能力边界与畏惧'),ev(10,4154,4156,'终局辩解')],(1,0,1,3,3,3),roles=['反派','阶段性协助者'] ))
C.append(make('mowang','魔王（五角星异星生命）',
'魔王的名字先于它的本体抵达人类社会，贪求财富、自由或爱情的人以自己的想象替这个称呼填上意义。原振侠真正见到它时，眼前是发着深灰光的五角星形生命，身处一个由它控制感知的异样空间。它需要人类灵魂所含的能量维持生命，积聚更多能量才可能回到来处，因此把满足愿望与取得灵魂组织成持续交易。它坚持每笔交易都出自自愿，却擅长制造自愿：以录音、求援、威胁或诱惑改变人的选择，再把被引导后的同意当作充分理由。林永兴将妻女卷入的悲剧暴露了这套说辞的漏洞，而原振侠拒绝为它传播教义时，它确实不能简单强夺他的意志，只得另找愿意承担的人。它可以在自己的空间里制造与真实无异的感受，却明确那不是外界真实物质随愿生成。终局洪致生和林雅儿成为新的招募者，自己的幸福与他人的风险同时延续。卡片不将它等同于神话中的绝对恶或宇宙级概念主宰；它是受生存需求和联系条件限制、却善于利用人性与语言的危险交易者。',
'未能说服原振侠，改与洪致生、林雅儿达成招募交易；仍在地球等待回归机会。',
[skill('联系、交易与感知空间','对已建立联系者传递声音，以愿望诱导同意；在自身空间中干预感受，并吸收受契约控制的灵魂能量。','五角星形光体、脑内声音和随念出现的体验。',['构造交易场景','控制已交出的灵魂相关意识','维持自身生命'],'需要联系与意愿条件；不能凭称号强夺所有意识，感知成真不是外界现实改写。')],
'获得维生及返乡所需的灵魂能量。',['把改变意愿包装成自愿交易','用愿望与代价维持供给','遇到不能说服的人就更换合作对象'],
[('对象有所渴求','愿望无法由普通条件满足','提出具体好处和延后代价，尤其利用对方不愿细想的后果。'),('意志明确拒绝','对方理解条件仍不合作','停止把话语当万能控制，转向其他安排。'),('契约被质疑','对方指出同意来自欺骗或替别人决定','以交换和既得好处辩解，暴露其伦理逻辑而非自动判它正确。')],
[ev(10,3880,3888,'联系条件'),ev(10,3965,4025,'本体、意愿与招募'),ev(10,4038,4126,'能量需求、限制与感知空间'),ev(10,4142,4156,'终局交易')],
(1,6,3,6,4,5),['本体常规力量不明','灵魂能量与意识干预','联系和契约限定对象','有持续生存与能量需求','脑内联系和特定空间','擅诱导而非无条件制服'],roles=['反派'],negative=(3,3,1),
body={'destruction':'吸收已受控制的灵魂能量可造成意识丧失，非任意灭城。','durability':'非人本体，无绝对不受影响的证明。','speed':'空间切换由其领域条件产生，反应速度未量化。','energy':'依赖灵魂能量维持生命，感知空间有局部条件。','mind':'能干预有关联者，明确拒绝并不一定能被强制突破。','stamina':'需能量供给，回归所需数量连本人也不能肯定。'}))
save('middle_a',C,[cov(10,[('原振侠','yuanzhenxia_yuanzhenxia','主角','调查与拒绝交易')]+[(c['name'],c['id'],c['roles'][0],'独立叙事或主要交易执行者') for c in C],[('贝壳潜水员、律师及仪式听众','一次性受害、传讯或背景角色')],['魔王仅是自选名称，能力受联系与意愿限制；头罩震荡是装置。'])])
